import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    texts = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    continue
                if isinstance(data, dict):
                    for v in data.values():
                        if isinstance(v, str):
                            texts.append(v)
                elif isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict):
                            for v in item.values():
                                if isinstance(v, str):
                                    texts.append(v)
                        elif isinstance(item, str):
                            texts.append(item)
    if not texts:
        return []
    df = pd.DataFrame({'text': texts})
    df['text'] = df['text'].str.lower()
    all_words = []
    for t in df['text']:
        words = pd.Series(t).str.replace(r'[^\w\s]', ' ', regex=True).str.split().explode()
        all_words.extend(words.dropna().tolist())
    counter = Counter(all_words)
    return counter.most_common(word_count)
