    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    properties = INPUT_JSON.get("properties", {})
    for key, prop in properties.items():
        if key in data:
            expected_type = prop.get("type")
            if expected_type is not None and not isinstance(data[key], expected_type):
                raise ValueError(f"Field '{key}' must be of type {expected_type.__name__}")

    email_value = data.get("email")
    if email_value is None or not isinstance(email_value, str) or not re.match(EMAIL_REGEX, email_value):
        raise ValueError("Invalid email format")

    if attribute not in data or attribute not in properties:
        raise ValueError(f"Attribute '{attribute}' is not valid or not present")

    expected_attr_type = properties[attribute].get("type")
    if expected_attr_type is not None and not isinstance(data[attribute], expected_attr_type):
        raise ValueError(f"Attribute '{attribute}' must be of type {expected_attr_type.__name__}")

    return data[attribute]
