import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    processed = {}
    number_pattern = re.compile(r'^[+-]?\d+(\.\d+)?$')
    for k, v in data.items():
        if isinstance(v, (int, float)):
            processed[k] = float(v) * 2
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                elif isinstance(item, str) and number_pattern.match(item.strip()):
                    new_list.append(float(item.strip()) * 2)
                else:
                    new_list.append(item)
            processed[k] = new_list
        elif isinstance(v, str):
            s = v.strip()
            if number_pattern.match(s):
                processed[k] = float(s) * 2
            else:
                processed[k] = v
        else:
            processed[k] = v
    try:
        df = pd.DataFrame(processed)
    except ValueError:
        return pd.DataFrame()
    if df.empty:
        return pd.DataFrame()
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='ignore')
    return df
