PREFIXES = ["is_", "has_", "can_", "should_"]
def task_func(directory):
    counts = {p: 0 for p in PREFIXES}
    def traverse(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                for p in PREFIXES:
                    if k.startswith(p):
                        counts[p] += 1
                traverse(v)
        elif isinstance(obj, list):
            for item in obj:
                traverse(item)
