```python
import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        obj = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}
    email_pattern = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
    collected_values = []
    def process(value):
        if value is None:
            return None
        if isinstance(value, dict):
            new_dict = {}
            for k, v in value.items():
                processed_v = process(v)
                if processed_v is not None:
                    new_dict[k] = processed_v
            return new_dict
        if isinstance(value, list):
            new_list = []
            for item in value:
                processed_item = process(item)
                if processed_item is not None:
                    new_list.append(processed_item)
            return new_list
        if isinstance(value, str):
            if email_pattern.fullmatch(value):
                value_replaced = REPLACE_NONE
            else:
                value_replaced = value
            collected_values.append(value_replaced)
            return value_replaced
        collected_values.append(value)
        return value
    processed_data = process(obj)
    value_counts = Counter(collected_values)
    return {"data": processed_data, "value_counts": value_counts}
