            values[k].append(v)
    result = {}
    for k, v_list in values.items():
        arr = np.array(v_list, dtype=float)
        result[k] = {
            "mean": float(np.mean(arr)),
            "median": float(np.median(arr))
        }
    with open(output_file, "w", newline="") as f:
